@startuml

class RepairShop {
  + Name : string
  + Address : string
  + NumberOfEmployees : int
}

class Employee {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
  + YearsOfService : int
}

class Director extends Employee {
  + Age : int
}

class Repair {
  + Code : string
  + CheckInDateTime : datetime
  + ReturnDateTime : datetime
}

class Vehicle {
  + Model : string
  + Type : string
  + LicensePlate : string
  + YearOfRegistration : int
}

class Owner {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
}

RepairShop "1" *-- "1..*" Employee : employs
RepairShop "1" -- "1" Director : directed by
RepairShop "1" -- "*" Repair : carries out
Repair "1" -- "1" Vehicle : involves
Vehicle "1" -- "1" Owner : owned by

@enduml

